"""Load the data package and check a claim the way the arena does (brief/api.md, « What counts »).

Prices in the data and in the case file are both per the part's `price_unit` (per 1, 100 or 1000 pieces):
compare them as they are, never divided (P14: case price 316.35 = last order line 316.35, per 100).
"""

import os
from functools import cache
from pathlib import Path
from statistics import mean

from arena_kit.data import DataPackage
from hollerau.contracts import Claim

# Where the package usually sits: ARENA_DATA, this repo's data/package (`uv run arena data`), or a kit clone.
CANDIDATES = [
    os.environ.get("ARENA_DATA"),
    Path(__file__).resolve().parents[2] / "data" / "package",
    Path("~/Projets/negotiation-arena-kit/starter-kit/data/package").expanduser(),
]

PCT_TOL = 0.5  # percentage points
REL_TOL = 0.005  # ±0.5 %, at least 0.01
MAX_ORDERS = 8


def load_package() -> DataPackage:
    for c in CANDIDATES:
        if c and (Path(c) / "facts.json").is_file():
            return DataPackage(c)
    raise FileNotFoundError("no data package: run `uv run arena data` or set ARENA_DATA")


@cache
def _package_facts() -> dict:
    try:
        return load_package().facts
    except FileNotFoundError:
        return {}


def facts_of(case: dict, data: DataPackage | None = None) -> dict:
    """Every fact citable in this case: package, Sunday release, and the case's own `facts`.
    Without `data`, the package found on disk (empty if none)."""
    base = data.facts if data is not None else _package_facts()
    return base | (case.get("facts") or {})


def asked_price(case: dict, facts: dict) -> float | None:
    """The price the supplier's letter asks for (`asked_price` of the trigger doc), if any."""
    doc = facts.get(case.get("trigger_doc") or "") or {}
    return doc.get("asked_price")


def series_change_pct(facts: dict, earlier: str, later: str) -> float:
    a, b = facts[earlier], facts[later]
    if a["series"] != b["series"]:
        raise ValueError("an index claim compares one series")
    return (b["value"] / a["value"] - 1) * 100


def close(figure: float, truth: float, unit: str) -> bool:
    if unit == "%":
        return abs(figure - truth) <= PCT_TOL
    return abs(figure - truth) <= max(abs(truth) * REL_TOL, 0.01)


def _orders_ok(claim: Claim, facts: dict) -> bool:
    rows = [facts[i] for i in claim.ids]
    return (
        2 <= len(rows) <= MAX_ORDERS
        and all(i.startswith("po:") for i in claim.ids)
        and len({r["part"] for r in rows}) == 1
    )


def _fcn_ok(claim: Claim, facts: dict) -> bool:
    """forecast_cost_news: one `fc` (change %), one `cost` (estimate EUR) or one `news` (no figure)."""
    if len(claim.ids) != 1:
        return False
    i, row = claim.ids[0], facts[claim.ids[0]]
    if i.startswith("news:"):
        return claim.figure is None
    if claim.figure is None:
        return i.startswith(("fc:", "cost:"))
    if i.startswith("fc:"):
        return claim.unit == "%" and close(claim.figure, row["change_pct"], "%")
    if i.startswith("cost:"):
        return claim.unit == "EUR" and close(claim.figure, row["unit_cost"], "EUR")
    return False


def check(claim: Claim, facts: dict) -> bool:
    """True if every ID exists and the figure matches the data within the arena's tolerance."""
    if not claim.ids or any(i not in facts for i in claim.ids):
        return False
    family, fig = claim.family, claim.figure
    if family == "orders":
        return _orders_ok(claim, facts)  # checked against the order prices: no figure of ours
    if family == "forecast_cost_news":
        return _fcn_ok(claim, facts)
    if fig is None:
        return True
    if family == "index":
        return len(claim.ids) == 2 and close(fig, series_change_pct(facts, *claim.ids), "%")
    if family == "notice":
        doc = next((facts[i] for i in claim.ids if i.startswith("doc:")), None)
        ctr = next((facts[i] for i in claim.ids if i.startswith("ctr:")), None)
        return bool(doc and ctr) and doc.get("days") == fig and doc["days"] < ctr["days"]
    if family == "quote":
        return (
            len(claim.ids) == 1
            and claim.ids[0].startswith("quote:")
            and close(fig, facts[claim.ids[0]]["unit_price"], "EUR")
        )
    if family == "scorecard":
        rows = [facts[i] for i in claim.ids]
        if not all(i.startswith(("sc:", "qn:")) for i in claim.ids):
            return False
        if claim.unit == "ppm":
            return close(fig, mean(r["ppm"] for r in rows), "ppm")
        if claim.unit == "%":
            return all(i.startswith("sc:") for i in claim.ids) and close(fig, mean(r["otd_pct"] for r in rows), "%")
        return False
    raise NotImplementedError(f"check for family {family}")
"""compile_case(case, standard) -> Economics: what each term sheet costs us, and which levers matter most.

All arithmetic is the kit's (`arena_kit.cost`). `cost` is the C the arena charges: no supplier estimate,
hence no relationship term (decision D1); `relationship_risk` exposes that estimate apart, as a warning.
Allowed values come from `term_options` only (decision D2). Levers are valued at the price the supplier's letter
asks for, else the current price (decision D3). Recompile once the quote's standard terms are read.
"""

import itertools
import logging
import math

from arena_kit import cost as kit
from hollerau.contracts import Economics, Lever, Terms

from .facts import asked_price, facts_of

log = logging.getLogger(__name__)

MAX_GRID = 5000  # beyond this many combinations, coordinate descent instead of exhaustive search


def _current_price(case: dict) -> float:
    b = case["buyer"]
    return b.get("current_unit_price") or b["fallback_unit_price"]


def lever_price(case: dict, data=None) -> float:
    """The price levers are valued at (D3): the letter's `asked_price`, else the current price. At the current
    price a later effective date is worth nothing, while the supplier asks for more."""
    return asked_price(case, facts_of(case, data)) or _current_price(case)


def _c_alt(case: dict) -> float:
    alt = case["buyer"].get("alternative") or {}
    if alt.get("kind", "none") == "none" or not alt.get("terms"):
        return math.inf
    return kit.total_cost(case, alt["terms"])  # inf without a price


def _grid(case: dict) -> dict[str, list]:
    """Allowed values of each negotiable non-price field; a field without options keeps the buyer's plan."""
    plan = kit.closing_terms(case, {})
    grid = {}
    for field in case["negotiable"]:
        if field == "unit_price":
            continue
        options = case.get("term_options", {}).get(field)
        if not options:
            log.warning("%s: negotiable field %s has no term_options, kept at the buyer's plan", case["case_id"], field)
            grid[field] = [plan.get(field)]
        else:
            grid[field] = list(options)
    return grid


def _search(grid: dict[str, list], c, ok) -> Terms:
    """The must-have-compatible combination of least C (first one on ties)."""
    fields = list(grid)
    valid = (t for t in (dict(zip(fields, combo, strict=True)) for combo in itertools.product(*grid.values())) if ok(t))
    if math.prod(len(v) for v in grid.values()) <= MAX_GRID:
        valid = list(valid)
        if not valid:
            raise ValueError("no combination of term_options meets the must-haves")
        return min(valid, key=c)
    best = next(valid, None)
    if best is None:
        raise ValueError("no combination of term_options meets the must-haves")
    improved = True
    while improved:
        improved = False
        for f in fields:
            for v in grid[f]:
                t = {**best, f: v}
                if ok(t) and c(t) < c(best):
                    best, improved = t, True
    return best


def compile_case(case: dict, standard: Terms | None = None, data=None) -> Economics:
    """`standard`: the supplier's standard terms from its quote PDF (`arena_kit.docs.standard_terms`).
    Unknown before round 0: the planner recompiles once the quote is read. `data`: the package (with the
    Sunday release); by default the one found on disk. `reference_price` is the lever price (D3)."""
    ref = lever_price(case, data)

    def cost(terms: Terms) -> float:
        return kit.total_cost(case, terms, standard)

    def must_haves_ok(terms: Terms) -> bool:
        return kit.must_haves_ok(case, terms, standard)

    def c(t: Terms) -> float:
        return cost({**t, "unit_price": ref})

    def ok(t: Terms) -> bool:
        return must_haves_ok({**t, "unit_price": ref})

    grid = _grid(case)
    best = _search(grid, c, ok)
    levers = []
    for field, options in grid.items():
        if field not in case.get("term_options", {}) or not case["term_options"][field]:
            continue
        valid = [v for v in options if ok({**best, field: v})]
        worst = max(valid, key=lambda v, f=field: c({**best, f: v}))
        levers.append(Lever(field, best[field], worst, round(c({**best, field: worst}) - c(best), 2)))
    levers.sort(key=lambda lv: lv.cost_of_forgetting_eur, reverse=True)
    return Economics(case["case_id"], cost, must_haves_ok, levers, best, _c_alt(case), ref)


def estimate_supplier(case: dict, data=None, standard: Terms | None = None) -> dict:
    """Our estimate of the supplier for `arena_kit.cost.supplier_value`: full cost from the should-cost
    (`cost:<part>`, single-part cases, per the part's price_unit like the case price), else the current price
    less the case's sustainable margin (it is assumed at break-even, marked `estimated`)."""
    b = case["buyer"]
    full, estimated = None, True
    if data is not None and len(case.get("parts", [])) == 1:
        row = data.facts.get("cost:" + case["parts"][0].split(":", 1)[1])
        if row:
            full, estimated = row["unit_cost"], False
    if full is None:
        full = _current_price(case) * (1 - (b.get("sustainable_margin_pct") or 0) / 100)
    std = {k: v for k, v in kit.closing_terms(case, {}, standard).items() if k != "unit_price"}
    return {"full_cost": full, "estimated": estimated, "interest_rate": b["interest_rate"], "standard": std}


def relationship_risk(case: dict, terms: Terms, standard: Terms | None = None, supplier=None, data=None) -> float:
    """EUR the deal would cost in relationship (stabilise / secure_supply) on our estimate of the supplier.
    A warning for the planner: the arena's C (`Economics.cost`) does not include it."""
    supplier = supplier or estimate_supplier(case, data, standard)
    return kit.relationship_cost(case, terms, standard, supplier)

