"""Load the data package and check a claim the way the arena does (brief/api.md, « What counts »).

Prices in the data and in the case file are both per the part's `price_unit` (per 1, 100 or 1000 pieces):
compare them as they are, never divided (P14: case price 316.35 = last order line 316.35, per 100). A row in
another price unit, or a bundle (one price for a kit of parts), is not comparable with the case price at all.

Never raise out of this lane: a fact with a missing or null field is skipped, a check that cannot be made is False.
"""

import csv
import logging
import os
from datetime import date
from pathlib import Path
from statistics import mean

from arena_kit.data import DataPackage
from hollerau.contracts import Claim

log = logging.getLogger(__name__)

# Where the package usually sits: ARENA_DATA, this repo's data/package (`uv run arena data`), or a kit clone.
REPO_PACKAGE = Path(__file__).resolve().parents[2] / "data" / "package"
KIT_PACKAGE = Path("~/Projets/negotiation-arena-kit/starter-kit/data/package").expanduser()

PCT_TOL = 0.5  # percentage points
REL_TOL = 0.005  # ±0.5 %, at least 0.01
MAX_ORDERS = 8
BUNDLE_TYPES = {"bundling"}

_loaded: DataPackage | None = None  # only a package that loaded is kept: a failure is retried on the next call


def load_package() -> DataPackage:
    for c in (os.environ.get("ARENA_DATA"), REPO_PACKAGE, KIT_PACKAGE):  # ARENA_DATA read at call time
        if c and (Path(c) / "facts.json").is_file():
            return DataPackage(c)
    raise FileNotFoundError("no data package: run `uv run arena data` or set ARENA_DATA")


def package(data: DataPackage | None = None) -> DataPackage | None:
    """`data` when given (pass it in the final: package + Sunday release), else the package on disk, else None."""
    global _loaded
    if data is not None:
        return data
    if _loaded is None:
        try:
            _loaded = load_package()
        except FileNotFoundError:
            log.warning("no data package found: facts are the case's own only")
            return None
    return _loaded


def facts_of(case: dict, data: DataPackage | None = None) -> dict:
    """Every fact citable in this case: package, Sunday release, and the case's own `facts`."""
    p = package(data)
    base = p.facts if p is not None else {}
    own = case.get("facts") if isinstance(case.get("facts"), dict) else {}
    return base | own


def has(row, *keys) -> bool:
    """True if `row` is a dict whose `keys` are all present and not null."""
    return isinstance(row, dict) and all(row.get(k) is not None for k in keys)


def asked_price(case: dict, facts: dict) -> float | None:
    """The price the supplier's letter asks for (`asked_price` of the trigger doc), if any."""
    doc = facts.get(case.get("trigger_doc") or "")
    return doc.get("asked_price") if isinstance(doc, dict) else None


def stake_price(case: dict, facts: dict) -> float | None:
    """The price a rival quote or our should-cost must beat to be worth citing: the lower of the current price and
    the asked price. A rival above today's price would anchor the supplier there."""
    prices = [p for p in (case.get("buyer", {}).get("current_unit_price"), asked_price(case, facts)) if p]
    return min(prices) if prices else None


def is_bundle(case: dict) -> bool:
    return case.get("type") in BUNDLE_TYPES or len(case.get("parts") or []) > 1


def part_price_unit(data, part: str) -> int:
    """The part's price unit (parts table), 1 when unknown."""
    p = package(data)
    if p is None or p.db is None:
        return 1
    rows = p.query("SELECT price_unit FROM parts WHERE id = ?", (part,))
    return (rows[0]["price_unit"] if rows else None) or 1


def comparable(case: dict, data, row: dict) -> bool:
    """A quote or should-cost row can be set against the case price: one part (no kit), same price unit."""
    if is_bundle(case) or not has(row, "part") or row["part"] not in (case.get("parts") or []):
        return False
    return (row.get("price_unit") or 1) == part_price_unit(data, row["part"])


def _day(value) -> date | None:
    try:
        return date.fromisoformat(str(value)[:10]) if value else None
    except ValueError:
        return None


def case_start(case: dict, facts: dict) -> date | None:
    """When the case starts: its own `start_date`, else the latest dated fact (package + Sunday release). News and
    letters up to then are known to us, even when they are later than the supplier's letter."""
    if d := _day(case.get("start_date")):
        return d
    days = [d for f in facts.values() if isinstance(f, dict) and (d := _day(f.get("date")))]
    return max(days) if days else None


def release_rows(data, table: str) -> list[dict]:
    """Rows of a Sunday-release table (`data/<table>.csv`): the release is not in the SQLite file."""
    p = package(data)
    path = p.release / "data" / f"{table}.csv" if p is not None and p.release else None
    if path is None or not path.is_file():
        return []
    try:
        with path.open(encoding="utf-8", newline="") as f:
            return list(csv.DictReader(f))
    except (OSError, csv.Error):
        log.exception("cannot read release table %s", table)
        return []


def series_change_pct(facts: dict, earlier: str, later: str) -> float:
    a, b = facts[earlier], facts[later]
    if a["series"] != b["series"]:
        raise ValueError("an index claim compares one series")
    return (b["value"] / a["value"] - 1) * 100


def close(figure: float, truth: float, unit: str) -> bool:
    if unit == "%":
        return abs(figure - truth) <= PCT_TOL
    return abs(figure - truth) <= max(abs(truth) * REL_TOL, 0.01)


def _orders_ok(claim: Claim, facts: dict) -> bool:
    rows = [facts[i] for i in claim.ids]
    return (
        2 <= len(rows) <= MAX_ORDERS
        and all(i.startswith("po:") for i in claim.ids)
        and len({r["part"] for r in rows}) == 1
    )


def _fcn_ok(claim: Claim, facts: dict) -> bool:
    """forecast_cost_news: one `fc` (change %), one `cost` (estimate EUR) or one `news` (no figure)."""
    if len(claim.ids) != 1:
        return False
    i, row = claim.ids[0], facts[claim.ids[0]]
    if i.startswith("news:"):
        return claim.figure is None
    if claim.figure is None:
        return i.startswith(("fc:", "cost:"))
    if i.startswith("fc:"):
        return claim.unit == "%" and close(claim.figure, row["change_pct"], "%")
    if i.startswith("cost:"):
        return claim.unit == "EUR" and close(claim.figure, row["unit_cost"], "EUR")
    return False


def _check(claim: Claim, facts: dict) -> bool:
    if not claim.ids or any(i not in facts for i in claim.ids):
        return False
    family, fig = claim.family, claim.figure
    if family == "orders":
        return _orders_ok(claim, facts)  # checked against the order prices: no figure of ours
    if family == "forecast_cost_news":
        return _fcn_ok(claim, facts)
    if fig is None:
        return True
    if family == "index":
        return len(claim.ids) == 2 and close(fig, series_change_pct(facts, *claim.ids), "%")
    if family == "notice":
        doc = next((facts[i] for i in claim.ids if i.startswith("doc:")), None)
        ctr = next((facts[i] for i in claim.ids if i.startswith("ctr:")), None)
        return has(doc, "days") and has(ctr, "days") and doc["days"] == fig and doc["days"] < ctr["days"]
    if family == "quote":
        return (
            len(claim.ids) == 1
            and claim.ids[0].startswith("quote:")
            and close(fig, facts[claim.ids[0]]["unit_price"], "EUR")
        )
    if family == "scorecard":
        rows = [facts[i] for i in claim.ids]
        if not all(i.startswith(("sc:", "qn:")) for i in claim.ids):
            return False
        if claim.unit == "ppm":
            return close(fig, mean(r["ppm"] for r in rows), "ppm")
        if claim.unit == "%":
            return all(i.startswith("sc:") for i in claim.ids) and close(fig, mean(r["otd_pct"] for r in rows), "%")
        return False
    return False  # a family the arena does not check: never send it


def check(claim: Claim, facts: dict) -> bool:
    """True if every ID exists and the figure matches the data within the arena's tolerance. Never raises: a fact
    with a missing or null field makes the claim unverifiable, so False."""
    try:
        return bool(_check(claim, facts))
    except (KeyError, TypeError, ValueError, ZeroDivisionError, AttributeError):
        return False

"""compile_case(case, standard, data) -> Economics: what each term sheet costs us, and which levers matter most.

All arithmetic is the kit's (`arena_kit.cost`). `cost` is the C the arena charges: no supplier estimate,
hence no relationship term (decision D1); `relationship_risk` exposes that estimate apart, as a warning.
Allowed values come from `term_options` only (decision D2). Levers are valued at the price the supplier's letter
asks for, else the current price (decision D3). Recompile once the quote's standard terms are read.

Never raises: a step that fails is logged and leaves its part empty (no levers, an empty package, c_alt inf).
"""

import itertools
import logging
import math

from arena_kit import cost as kit
from hollerau.contracts import Economics, Lever, Terms

from .facts import asked_price, comparable, facts_of, has

log = logging.getLogger(__name__)

MAX_GRID = 5000  # beyond this many combinations, coordinate descent instead of exhaustive search


def _current_price(case: dict) -> float:
    b = case.get("buyer") or {}
    return b.get("current_unit_price") or b.get("fallback_unit_price") or math.nan


def lever_price(case: dict, data=None) -> float:
    """The price levers are valued at (D3): the letter's `asked_price`, else the current price. At the current
    price a later effective date is worth nothing, while the supplier asks for more."""
    try:
        return asked_price(case, facts_of(case, data)) or _current_price(case)
    except Exception:
        log.exception("%s: lever price", case.get("case_id"))
        return _current_price(case)


def _c_alt(case: dict) -> float:
    alt = case["buyer"].get("alternative") or {}
    if alt.get("kind", "none") == "none" or not alt.get("terms"):
        return math.inf
    return kit.total_cost(case, alt["terms"])  # inf without a price


def _grid(case: dict) -> dict[str, list]:
    """Allowed values of each negotiable non-price field; a field without options keeps the buyer's plan."""
    plan = kit.closing_terms(case, {})
    grid = {}
    for field in case["negotiable"]:
        if field == "unit_price":
            continue
        options = case.get("term_options", {}).get(field)
        if not options:
            log.warning("%s: negotiable field %s has no term_options, kept at the buyer's plan", case["case_id"], field)
            grid[field] = [plan.get(field)]
        else:
            grid[field] = list(options)
    return grid


def _grid_must_haves(case: dict, grid: dict, standard: Terms | None) -> list[dict]:
    """The must-haves the grid search can test: not the price (the planner's call), not a field the term sheet does
    not carry and nobody has filled yet (a field only the supplier's quote fills, before round 0)."""
    known = kit.closing_terms(case, {}, standard)
    kept = []
    for m in case["buyer"].get("must_haves", []):
        f = m.get("field")
        if f == "unit_price" or (f not in grid and known.get(f) is None):
            log.warning("%s: must-have on %s left out of the term search", case["case_id"], f)
            continue
        kept.append(m)
    return kept


def _search(grid: dict[str, list], c, ok, case_id: str) -> Terms:
    """The must-have-compatible combination of least C (first one on ties). If none meets them, the cheapest one,
    with a warning: the planner must not send it as compatible."""
    fields = list(grid)
    combos = [dict(zip(fields, combo, strict=True)) for combo in itertools.product(*grid.values())][:MAX_GRID]
    valid = [t for t in combos if ok(t)]
    if not valid:
        log.warning("%s: no combination of term_options meets the must-haves; cheapest one returned", case_id)
        valid = combos
    if math.prod(len(v) for v in grid.values()) <= MAX_GRID:
        return min(valid, key=c)
    best, improved = valid[0], True
    while improved:
        improved = False
        for f in fields:
            for v in grid[f]:
                t = {**best, f: v}
                if ok(t) and c(t) < c(best):
                    best, improved = t, True
    return best


def compile_case(case: dict, standard: Terms | None = None, data=None) -> Economics:
    """`standard`: the supplier's standard terms from its quote PDF (`arena_kit.docs.standard_terms`).
    Unknown before round 0: the planner recompiles once the quote is read. `data`: the package with the Sunday
    release; pass it explicitly in the final (default: the package on disk). `reference_price` is the lever price."""
    case_id = case.get("case_id", "?") if isinstance(case, dict) else "?"
    ref = lever_price(case, data)

    def cost(terms: Terms) -> float:
        try:
            return kit.total_cost(case, terms, standard)
        except Exception:
            log.exception("%s: cost", case_id)
            return math.inf

    def must_haves_ok(terms: Terms) -> bool:
        try:
            return kit.must_haves_ok(case, terms, standard)
        except Exception:
            log.exception("%s: must-haves", case_id)
            return False

    try:
        c_alt = _c_alt(case)
    except Exception:
        log.exception("%s: c_alt", case_id)
        c_alt = math.inf

    best, levers = {}, []
    try:
        grid = _grid(case)
        search_case = {**case, "buyer": {**case["buyer"], "must_haves": _grid_must_haves(case, grid, standard)}}

        def c(t: Terms) -> float:
            return cost({**t, "unit_price": ref})

        def ok(t: Terms) -> bool:
            return kit.must_haves_ok(search_case, {**t, "unit_price": ref}, standard)

        best = _search(grid, c, ok, case_id)
        for field, options in grid.items():
            if not case.get("term_options", {}).get(field):
                continue
            valid = [v for v in options if ok({**best, field: v})] or [best[field]]
            worst = max(valid, key=lambda v, f=field: c({**best, f: v}))
            levers.append(Lever(field, best[field], worst, round(c({**best, field: worst}) - c(best), 2)))
        levers.sort(key=lambda lv: lv.cost_of_forgetting_eur, reverse=True)
    except Exception:
        log.exception("%s: term search failed, no levers", case_id)
        best, levers = {}, []
    return Economics(case_id, cost, must_haves_ok, levers, best, c_alt, ref)


def estimate_supplier(case: dict, data=None, standard: Terms | None = None) -> dict:
    """Our estimate of the supplier for `arena_kit.cost.supplier_value`: full cost from the should-cost
    (`cost:<part>`, when comparable with the case price: one part, same price unit), else the current price less
    the case's sustainable margin (it is assumed at break-even, marked `estimated`)."""
    b = case["buyer"]
    full, estimated = None, True
    facts = facts_of(case, data)
    for part in case.get("parts", [])[:1]:
        row = facts.get("cost:" + part.split(":", 1)[1])
        if has(row, "unit_cost") and comparable(case, data, row):
            full, estimated = row["unit_cost"], False
    if full is None:
        full = _current_price(case) * (1 - (b.get("sustainable_margin_pct") or 0) / 100)
    std = {k: v for k, v in kit.closing_terms(case, {}, standard).items() if k != "unit_price"}
    return {"full_cost": full, "estimated": estimated, "interest_rate": b["interest_rate"], "standard": std}


def relationship_risk(case: dict, terms: Terms, standard: Terms | None = None, supplier=None, data=None) -> float:
    """EUR the deal would cost in relationship (stabilise / secure_supply) on our estimate of the supplier.
    A warning for the planner: the arena's C (`Economics.cost`) does not include it. 0 if it cannot be estimated."""
    try:
        supplier = supplier or estimate_supplier(case, data, standard)
        return kit.relationship_cost(case, terms, standard, supplier)
    except Exception:
        log.exception("%s: relationship risk", case.get("case_id"))
        return 0.0

"""signals(case, data) -> dict: what the planner should know about the supplier, never sent as a claim.

Meeting notes, letters and e-mails are context, not checks (brief/api.md); our late payments are not citable
at all (no `inv:` in facts.json). The package's notes follow fixed wordings, so plain phrase matching is
reliable. Every signal lists the IDs it comes from, so the planner can quote the context in prose.
Documents come from the package (SQLite) and the Sunday release (`data/documents.csv`), up to the case's start:
a note later than the supplier's letter but known before the case is still ours to use.

  asked_pct, asked_price      the letter's demand (None without a price letter)
  weighted_index_pct          per part, the 12-month move of its cost drivers weighted by `cost_drivers`
  increase_justified          the weighted move meets the demand, within 1 point (P02): argue terms, not the price
  suppliers[sup]              per supplier:
    committee_above_pct       price changes above this % need its pricing committee
    material_hedged_until     "Month YYYY" its material or energy is bought forward to (P08, P14)
    cash_need, free_capacity, full_order_book, open_book, reference_customer, small_account_review,
    not_strategic, expects_partnership, list_price_only, overdue_complaints   -> list of IDs
    credit_index_change       supplier_intel credit index now minus 12 months ago (higher = worse)
    single_source             no other active or qualified source for a part of the case
    our_late_payments         {invoices, late_share, avg_days_late} over the 12 months before the case

Never raises: a section that fails is logged and left at its empty value.
"""

import logging
import re
from datetime import date, timedelta

from .facts import _day, asked_price, case_start, facts_of, package, release_rows
from .index import asked_pct, driver_moves, increase_justified, weighted_move_pct

log = logging.getLogger(__name__)

NOTE_DAYS = 548  # notes of the last 18 months
PAY_DAYS = 365

PHRASES = {
    "cash_need": ["pay earlier", "pay our invoices within", "spoke mostly about cash"],
    "free_capacity": ["could take additional parts at short notice"],
    "full_order_book": ["order intake is very strong", "very high capacity utilisation"],
    "open_book": ["walk us through their calculation"],
    "reference_customer": ["important reference customer"],
    "small_account_review": ["reviewing small accounts"],
    "not_strategic": ["'not strategic'"],
    "expects_partnership": ["expects partnership"],
    "list_price_only": ["are not discounted", "applies to all customers", "will not be extended"],
    "overdue_complaints": ["invoices are overdue"],
}
NEWS = {
    "free_capacity": "free_capacity",
    "new_plant": "free_capacity",
    "full_order_book": "full_order_book",
    "allocation": "full_order_book",
    "credit_downgrade": "cash_need",
    "credit_watch": "cash_need",
    "short_time_work": "cash_need",
}
COMMITTEE = re.compile(r"price changes above ([\d.]+) ?% need the approval")
HEDGED = re.compile(r"(?:forward|at fixed prices) until (\w+ \d{4})")


def _window(case: dict, facts: dict) -> tuple[date | None, date | None]:
    end = case_start(case, facts)
    return (end - timedelta(days=NOTE_DAYS) if end else None), end


def _inside(d: date | None, since: date | None, until: date | None) -> bool:
    return d is not None and not (since and d < since) and not (until and d > until)


def _documents(data, supplier: str, since: date | None, until: date | None) -> list[tuple[str, str]]:
    """(id, text) of the supplier's documents in the window: package, then Sunday release."""
    p = package(data)
    if p is None:
        return []
    rows = []
    if p.db is not None:
        rows = p.query("SELECT id, date FROM documents WHERE supplier_id = ? ORDER BY date", (supplier,), limit=1000)
    rows += [r for r in release_rows(data, "documents") if r.get("supplier_id") == supplier]
    out = []
    for r in rows:
        if not r.get("id") or not _inside(_day(r.get("date")), since, until):
            continue
        try:
            out.append((r["id"], " ".join(p.document(r["id"]).split())))
        except (FileNotFoundError, OSError, ValueError):
            log.warning("document %s unreadable, skipped", r["id"])
    return out


def _late_payments(data, supplier: str, until: date | None) -> dict:
    out = {"invoices": 0, "late_share": 0.0, "avg_days_late": 0.0}
    p = package(data)
    if p is None or p.db is None:
        return out
    end = until or date.max
    start = end - timedelta(days=PAY_DAYS) if until else date.min
    rows = p.query(
        "SELECT due_date, paid_date FROM invoices WHERE supplier_id = ? AND paid_date IS NOT NULL", (supplier,), limit=100_000
    )
    pairs = [(d, pd) for r in rows if (d := _day(r["due_date"])) and (pd := _day(r["paid_date"])) and start <= d <= end]
    late = [(pd - d).days for d, pd in pairs if pd > d]
    if pairs:
        out["invoices"] = len(pairs)
        out["late_share"] = round(len(late) / len(pairs), 3)
        out["avg_days_late"] = round(sum(late) / len(late), 1) if late else 0.0
    return out


def _single_source(data, case: dict, supplier: str) -> bool | None:
    """True if a part of the case has no other active or qualified source; None if sourcing is unknown."""
    p = package(data)
    if p is None or p.db is None:
        return None
    for part in case["parts"]:
        rows = p.query("SELECT supplier_id, status FROM sourcing WHERE part_id = ?", (part,))
        if not rows:
            return None  # a part we know nothing about: no claim either way
        others = [r for r in rows if r["supplier_id"] != supplier and r["status"] in ("active", "qualified")]
        if not others:
            return True
    return False


def _from_documents(out: dict, docs: list[tuple[str, str]]) -> None:
    for doc_id, text in docs:
        low = text.lower()
        for name, phrases in PHRASES.items():
            if any(p in low for p in phrases):
                out[name].append(doc_id)
        if m := COMMITTEE.search(low):
            out["committee_above_pct"] = float(m.group(1))
            out["committee"].append(doc_id)
        if m := HEDGED.search(text):
            out["material_hedged_until"] = m.group(1)
            out["material_hedged"].append(doc_id)


def _from_news(out: dict, facts: dict, supplier: str, since: date | None, until: date | None) -> None:
    for nid, n in sorted(facts.items()):
        if not nid.startswith("news:") or not isinstance(n, dict) or n.get("supplier") != supplier:
            continue
        if n.get("topic") in NEWS and _inside(_day(n.get("date")), since, until):
            out[NEWS[n["topic"]]].append(nid)


def supplier_signals(case: dict, data, facts: dict, supplier: str) -> dict:
    since, until = _window(case, facts)
    out: dict = {name: [] for name in PHRASES}
    out |= {"committee": [], "material_hedged": [], "committee_above_pct": None, "material_hedged_until": None}
    out |= {"credit_index_change": None, "single_source": None, "our_late_payments": _late_payments(None, "", None)}
    steps = {
        "documents": lambda: _from_documents(out, _documents(data, supplier, since, until)),
        "news": lambda: _from_news(out, facts, supplier, since, until),
        "credit": lambda: out.update(credit_index_change=_credit_change(data, supplier)),
        "sourcing": lambda: out.update(single_source=_single_source(data, case, supplier)),
        "payments": lambda: out.update(our_late_payments=_late_payments(data, supplier, until)),
    }
    for name, step in steps.items():
        try:
            step()
        except Exception:
            log.exception("%s: signals %s for %s failed, left empty", case.get("case_id"), name, supplier)
    return out


def _credit_change(data, supplier: str) -> int | None:
    p = package(data)
    if p is None or p.db is None:
        return None
    rows = p.query("SELECT credit_index, credit_index_12m_ago FROM supplier_intel WHERE supplier_id = ?", (supplier,))
    if not rows or rows[0]["credit_index"] is None or rows[0]["credit_index_12m_ago"] is None:
        return None
    return rows[0]["credit_index"] - rows[0]["credit_index_12m_ago"]


def saturated(case: dict, data, facts: dict, supplier: str) -> bool:
    """The supplier says its order book is full or allocates (notes, letters, news): more volume is its leverage."""
    since, until = _window(case, facts)
    out = {name: [] for name in PHRASES} | {"committee": [], "material_hedged": []}
    _from_documents(out, _documents(data, supplier, since, until))
    _from_news(out, facts, supplier, since, until)
    return bool(out["full_order_book"])


def signals(case: dict, data) -> dict:
    out = {"asked_pct": None, "asked_price": None, "weighted_index_pct": {}, "increase_justified": None, "suppliers": {}}
    try:
        facts = facts_of(case, data)
        out["asked_pct"] = asked = asked_pct(case, facts)
        out["asked_price"] = asked_price(case, facts)
    except Exception:
        log.exception("%s: signals unavailable", case.get("case_id") if isinstance(case, dict) else None)
        return out
    try:
        p = package(data)
        for part in case["parts"] if p is not None and p.db is not None else []:
            moves = driver_moves(part, p, facts)
            if moves:
                out["weighted_index_pct"][part] = round(weighted_move_pct(moves), 2)
        weighted = out["weighted_index_pct"]
        if asked is not None and weighted:
            out["increase_justified"] = any(increase_justified(w, asked) for w in weighted.values())
    except Exception:
        log.exception("%s: index signals failed", case.get("case_id"))
    for s in case.get("suppliers") or []:
        out["suppliers"][s] = supplier_signals(case, data, facts, s)
    return out

