"""Letter family: the supplier's own letter saying its material is covered at fixed prices (signal material_hedged).

Only without a price letter (raw material, renewal): there the supplier argues for an index clause, and its own
letter says market moves do not reach its costs before a date. Cited without a figure, supports `other` (the index
clause). Only the supplier's letters and e-mails: our own call and meeting notes are context, not checks
(brief/api.md). The arena has no row for a letter cited alone: its result is not known yet (at worst `irrelevant`,
never a wrong figure). `letter` is not in the family list of `hollerau/contracts.py`: to validate with Icham.
"""

from datetime import date, datetime

from hollerau.contracts import Claim

from .facts import _day, asked_price, case_start, has, package
from .signals import HEDGED

SUPPLIER_DOCS = {"letter", "email"}


def _until(text: str) -> tuple[str, date] | None:
    """('March 2027', 2027-03-01) from "... at fixed prices until March 2027 ...", else None."""
    if not (m := HEDGED.search(text)):
        return None
    try:
        return m.group(1), datetime.strptime(m.group(1), "%B %Y").date()
    except ValueError:
        return None


def letter_claims(case: dict, data, facts: dict) -> list[Claim]:
    if asked_price(case, facts) is not None:
        return []
    p, start = package(data), case_start(case, facts)
    if p is None:
        return []
    claims = []
    for doc_id in sorted(i for i in facts if i.startswith("doc:")):
        doc = facts[doc_id]
        if not has(doc, "supplier", "date", "type") or doc["supplier"] not in case["suppliers"]:
            continue
        sent = _day(doc["date"])
        if doc["type"] not in SUPPLIER_DOCS or sent is None or (start and sent > start):
            continue
        try:
            hedge = _until(" ".join(p.document(doc_id).split()))
        except (FileNotFoundError, OSError, ValueError):
            continue
        if hedge is None or (start and hedge[1] < start.replace(day=1)):
            continue  # no cover, or it has already run out
        claims.append(
            Claim(
                family="letter",
                ids=[doc_id],
                figure=None,
                unit="",
                sentence=f"Your letter of {doc['date']} ({doc_id}) says your material is covered until {hedge[0]}.",
                supports="other",
            )
        )
    return claims

