"""Play a case with one worker per supplier thread, so no thread waits on another's reply.

The kit's `play` sends one message at a time: in an RFQ the other threads' 60-second clocks run
out while one supplier takes a minute to answer. Here every thread has its own worker; decisions
share one agent under a lock; the first accept or walk-away ends the case for all.
"""

import logging
import threading
import time
from concurrent.futures import ThreadPoolExecutor

from arena_kit.client import ArenaError
from arena_kit.play import (
    CLOSE_BEFORE_CAP_S,
    ENDED,
    ROUND_MARGIN_S,
    RemoteTable,
    closing_move,
    fetch_documents,
    latest,
    standing,
)

log = logging.getLogger("pegasus")


def play_case(table, case_id, agent, deadline=None):
    case, threads = table.open(case_id)
    if getattr(table, "done", None):
        return table.done
    for events in threads.values():
        for m in events:
            fetch_documents(table, m)
    lock, done = threading.Lock(), threading.Event()
    box, slowest, inflight = {}, [0.0], set()

    def finish(sid, msg):
        """Close the case; False if the arena refused (e.g. a stale sheet) - then decide again."""
        try:
            box["result"] = table.close(sid, msg)
        except ArenaError as e:
            log.warning("%s: close failed: %s", case_id, e.detail)
            if e.status in (409, 422) and table.client.session(table.session_id).get("status") != "ended":
                return False
            box["result"] = table.result()
        done.set()
        return True

    def worker(sid):
        while not done.is_set():
            t0 = time.monotonic()
            with lock:
                if done.is_set() or latest(threads[sid]).get("status") in ENDED:
                    return
                cap = deadline() if callable(deadline) else deadline
                if cap and time.time() > cap - max(CLOSE_BEFORE_CAP_S, slowest[0] + ROUND_MARGIN_S):
                    decision = closing_move(case, threads)
                else:
                    decision = agent.decide(case, threads, sid, busy=inflight - {sid})
                if decision is None:
                    return
                waiting = bool(decision.get("wait"))
            if waiting:
                time.sleep(1.0)
                continue
            with lock:
                if done.is_set():
                    return
                dsid, msg = decision["supplier_id"], decision["message"]
                if msg.get("action"):
                    log.info("%s %s %s", case_id, dsid, msg["action"])
                    if finish(dsid, msg):
                        return
                    # refused (e.g. the sheet went stale): resync that thread from the arena
                    try:
                        fresh = table.client.thread(table.session_id, dsid)["messages"]
                        threads[dsid] = [fetch_documents(table, m) for m in fresh]
                    except ArenaError as e:
                        log.warning("%s: resync failed: %s", case_id, e.detail)
                        return
                    continue
                inflight.add(dsid)
            try:
                reply = table.send(dsid, msg)
            except ArenaError as e:
                with lock:
                    inflight.discard(dsid)
                if e.status != 409:
                    log.warning("%s %s: %s", case_id, dsid, e.detail)
                    if e.status == 422:  # an invalid message uses no round: log and stop this thread
                        return
                    raise
                reply = table.missed(dsid, e)
            with lock:
                inflight.discard(dsid)
            if "result" in reply:
                box["result"] = reply["result"]
                done.set()
                return
            with lock:
                threads[dsid] += [{**msg, "from": "buyer"}, fetch_documents(table, reply)]
                slowest[0] = max(slowest[0], time.monotonic() - t0)
                log.info("%s %s %s %s", case_id, dsid, reply.get("status"), standing(threads[dsid])[1])

    with ThreadPoolExecutor(max_workers=len(threads)) as pool:
        list(pool.map(worker, list(threads)))
    return box.get("result") or table.result()


def play_cases(client, case_ids, new_agent, parallel=5):
    def one(cid):
        try:
            return cid, play_case(RemoteTable(client), cid, new_agent())
        except Exception as e:
            log.exception("%s failed", cid)
            return cid, e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        return dict(pool.map(one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    """The Live Final, like the kit's `play_waves`, with the per-thread player."""
    import functools

    started, closed, caps = {}, set(), {}

    def one(case, deadline):
        try:
            return play_case(RemoteTable(client, case), case["case_id"], new_agent(), deadline)
        except Exception as e:
            log.exception("%s failed", case["case_id"])
            return e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                cases = client.cases("final")
            except ArenaError as e:
                if e.status != 403:
                    raise
                cases = []
            for case in cases:
                if not case.get("open"):
                    closed.add(case["wave"])
                    continue
                if case.get("seconds_left") is not None:
                    caps[case["wave"]] = time.time() + case["seconds_left"]
                if case["case_id"] not in started and case.get("seconds_left"):
                    log.warning("wave %s: %s", case["wave"], case["case_id"])
                    started[case["case_id"]] = pool.submit(one, case, functools.partial(caps.get, case["wave"]))
            time.sleep(poll)
    return {cid: f.result() for cid, f in started.items()}

"""Absolute rule: no arena session is opened without the user's validation.

Every entry point that can open a session on a hosted arena calls `require_validation` first.
The local simulator (localhost) is free. Validation is given per launch, on the command line:
  HOLLERAU_VALIDATED="who said yes, for what" uv run ...
"""

import os
import sys
from urllib.parse import urlparse

LOCAL = {"127.0.0.1", "localhost", "::1"}


def is_local(url=None):
    return (urlparse(url or os.environ.get("ARENA_URL", "")).hostname or "") in LOCAL


def require_validation(what, sessions, quota=False):
    """Stop unless the user validated this launch. `sessions`: how many it opens; `quota`: counts on the 200."""
    if is_local():
        return
    ok = os.environ.get("HOLLERAU_VALIDATED", "").strip()
    kind = "PRACTICE (counts against the 200 per 24 h)" if quota else "sandbox (off quota)"
    if not ok:
        sys.exit(
            f"REFUSED: {what} would open {sessions} session(s), {kind}.\n"
            "Rule: no session without the user's validation. Ask, then relaunch with\n"
            '  HOLLERAU_VALIDATED="<who validated, for what>" ...'
        )
    print(f"[sessions] {what}: {sessions} session(s), {kind} - validated: {ok}", file=sys.stderr)
"""Read-only access to the data package: SQL, lookup by citable ID, documents, practice cases -
plus the Sunday release (new news, letters and a memo) once you have downloaded it."""

import csv
import json
import os
import sqlite3
from functools import cached_property
from pathlib import Path

MAX_ROWS = 200
RELEASE = "release-sunday"


class DataPackage:
    def __init__(self, root, release=None):
        """`root`: the unpacked package. `release`: the unpacked Sunday release (default: a
        `release-sunday` folder inside or next to the package, or ARENA_RELEASE), if present."""
        self.root = Path(root).expanduser().resolve()
        # facts.json holds every citable fact with the fields the arena checks claims against.
        own = self.root / "facts.json"
        facts = [own] if own.is_file() else [p for p in sorted(self.root.rglob("facts.json")) if RELEASE not in p.parts]
        self.facts = json.loads(facts[0].read_text(encoding="utf-8")) if facts else {}
        release = release or os.environ.get("ARENA_RELEASE")
        candidates = [Path(release).expanduser()] if release else [self.root / RELEASE, self.root.parent / RELEASE]
        self.release = next((p.resolve() for p in candidates if (p / "facts.json").is_file()), None)
        if self.release:  # new IDs only: nothing in the package changes
            self.facts |= json.loads((self.release / "facts.json").read_text(encoding="utf-8"))
        dbs = sorted(self.root.rglob("*.sqlite")) + sorted(self.root.rglob("*.db"))
        if not dbs and not facts:
            raise FileNotFoundError(f"no facts.json or .sqlite under {self.root}")
        self.db = None
        if dbs:
            self.db = sqlite3.connect(f"file:{dbs[0]}?mode=ro", uri=True, check_same_thread=False)
            self.db.row_factory = sqlite3.Row
            self.db.execute("PRAGMA query_only = ON")

    def tables(self):
        """{table: {"columns": [...], "rows": n}}"""
        if self.db is None:
            return {}
        names = [r[0] for r in self.db.execute("SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name")]
        return {
            t: {
                "columns": [f"{c[1]} {c[2]}".strip() for c in self.db.execute(f'PRAGMA table_info("{t}")')],
                "rows": self.db.execute(f'SELECT count(*) FROM "{t}"').fetchone()[0],
            }
            for t in names
        }

    def query(self, sql, params=(), limit=MAX_ROWS):
        if self.db is None:
            raise ValueError("this package has no SQLite file")
        if sql.lstrip().split(None, 1)[0].lower() not in {"select", "with"}:
            raise ValueError("read-only: SELECT or WITH statements only")
        cur = self.db.execute(sql, params)
        return [dict(r) for r in cur.fetchmany(limit)]

    @cached_property
    def _ids(self):
        # A table's citable ID sits in its `id` column, else in its first column.
        index = {}
        for t, meta in self.tables().items():
            cols = [c.split()[0] for c in meta["columns"]]
            key = "id" if "id" in cols else cols[0]
            for row in self.db.execute(f'SELECT * FROM "{t}"'):
                value = row[key]
                if isinstance(value, str) and ":" in value:
                    index[value] = {"table": t, **dict(row)}
        for path in sorted(self.release.glob("data/*.csv")) if self.release else []:  # not in the SQLite
            with path.open(encoding="utf-8", newline="") as f:
                for row in csv.DictReader(f):
                    index[row["id"]] = {"table": path.stem, **row, "root": str(self.release)}
        return index

    def lookup(self, ref):
        """The fact behind a citable ID (from facts.json, else its table row), or None."""
        return self.facts.get(ref) or self._ids.get(ref)

    def ids(self, prefix):
        """All citable IDs starting with `prefix`, sorted, e.g. ids("idx:GP19-245113@")."""
        return sorted(i for i in self.facts.keys() | self._ids.keys() if i.startswith(prefix))

    def document(self, ref):
        """A document's text by ID (row with a path or body column) or by path in the package."""
        row, base = self._ids.get(ref) or self.facts.get(ref), self.root
        if row:
            for col in ("body", "text", "content"):
                if row.get(col):
                    return row[col]
            base = Path(row.get("root") or self.root)
            ref = next((row[c] for c in ("path", "file") if row.get(c)), None)
            if ref is None:
                return json.dumps(row, ensure_ascii=False)
        path = (base / ref).resolve()
        if not path.is_relative_to(base) or not path.is_file():
            raise FileNotFoundError(ref)
        return path.read_text(encoding="utf-8")

    @cached_property
    def cases(self):
        """Practice (and demo) case files in the package: {case_id: case}."""
        out = {}
        for p in sorted(self.root.rglob("cases/**/*.json")):
            case = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(case, dict) and "case_id" in case:
                out[case["case_id"]] = case
        return out

