    """{case_id: (session_id, case)} of this team's sessions still open in `set_` - empty if they cannot be read.
    Practice and sandbox never answer 409 with the running session (the final does): without this, a restarted
    runner opens new sessions, the old ones stay open until the clock ends them, and at 10 open the arena
    refuses every new one (429)."""
    try:
        running = {}
        for s in sorted(client.sessions(set_), key=lambda s: s.get("created_at") or 0):
            if s.get("status") == "open":
                running[s["case_id"]] = s["session_id"]  # the most recent one wins
        if not running:
            return {}
        cases = {c["case_id"]: c for c in client.cases(set_)}
        return {cid: (sid, cases[cid]) for cid, sid in running.items() if cid in cases}
    except Exception:
        log.exception("could not list the open sessions: none resumed")
        return {}


